begin;
select no_plan();
insert into public.profiles(id) values('19100800-0000-4000-8000-000000000001'),('19100800-0000-4000-8000-000000000002'),('19100800-0000-4000-8000-000000000003');
select * from public.operational_access_set('19100800-0000-4000-8000-000000000001','owner','grant','fixture','Sync owner','sync-owner',null);
select * from public.operational_access_set('19100800-0000-4000-8000-000000000003','owner','grant','fixture','Expired sync owner','sync-expired',null);
update public.operational_access_assignments set granted_at=now()-interval '2 days',expires_at=now()-interval '1 day' where user_id='19100800-0000-4000-8000-000000000003';
select throws_ok($$select public.native_admin_payment_sync_budget('19100800-0000-4000-8000-000000000002','sandbox')$$,'42501','native_admin_forbidden','non-owner cannot spend sync quota');
select throws_ok($$select public.native_admin_payment_sync_budget('19100800-0000-4000-8000-000000000003','sandbox')$$,'42501','native_admin_forbidden','expired owner cannot spend sync quota');
select is((select count(*)::integer from private.admin_payment_sync_budget),0,'rejected callers do not create quota rows');
select throws_ok($$select public.native_admin_payment_sync_budget('19100800-0000-4000-8000-000000000001','production')$$,'42501','native_admin_forbidden','sync stays sandbox only');
select ok(public.native_admin_payment_sync_budget('19100800-0000-4000-8000-000000000001','sandbox'),'first owner import allowed');
select ok(not public.native_admin_payment_sync_budget('19100800-0000-4000-8000-000000000001','sandbox'),'repeated import has its own quota');
update private.admin_payment_sync_budget set window_start=clock_timestamp()-interval '61 seconds';
select ok(public.native_admin_payment_sync_budget('19100800-0000-4000-8000-000000000001','sandbox'),'expired window allows retry');
select ok(not has_function_privilege('anon','public.native_admin_payment_sync_budget(uuid,text,uuid)','EXECUTE'),'anon cannot execute sync budget');
select ok(not has_function_privilege('authenticated','public.native_admin_payment_sync_budget(uuid,text,uuid)','EXECUTE'),'authenticated cannot execute sync budget');
select ok(not has_table_privilege('service_role','private.admin_payment_sync_budget','SELECT'),'quota table is not exposed to service role');
select * from finish();
rollback;
